            t=" | ".join(p.text for p in shp.text_frame.paragraphs if p.text.strip())
            if t.strip():
                print(f"[TEXT] {t}")
        if shp.has_table:
            print("[TABLE]")
            for row in shp.table.rows:
                print("   ", " | ".join(c.text for c in row.cells))
        if shp.shape_type==6:
            print("[PICTURE] name=", shp.name)
PY", "description": "Extract text from pptx slides"}

