{"command": "cd __FDE_WORKSPACE_PATH__ && python3 - <<'PY'
import zipfile
from lxml import etree
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
path="fde-resources/01-项目需求初稿.docx"
z=zipfile.ZipFile(path)
root=etree.fromstring(z.read('word/document.xml'))
body=root.find('w:body',ns)
def para_text(p):
    return ''.join(t.text or '' for t in p.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t'))
for child in body:
    tag=etree.QName(child).localname
    if tag=='p':
        txt=para_text(child).strip()
        if txt:
            print(txt)
    elif tag=='tbl':
        print("[TABLE]")
        for tr in child.findall('w:tr',ns):
            cells=[]
            for tc in tr.findall('w:tc',ns):
                cells.append(' '.join(para_text(p) for p in tc.findall('w:p',ns)).strip())
            print("   ", " | ".join(cells))
PY", "description": "Extract docx requirement draft text and tables"}

