{"meta": {"name": "code-readiness-audit", "description": "并行审阅 Northlight 前后端代码，按 PRD 功能项与安全要求评估支撑度", "whenToUse": "开发启动前的代码支撑度/缺口审计", "phases": [{"title": "后端能力审阅", "detail": "数据/查询/分析/模型/报告/Skills"}, {"title": "前端与测试审阅", "detail": "页面与接口消费、测试与脚本"}]}, "script": "// 公共 FR 清单（来自 project-prd.md）
const FR_LIST = `FR-1 项目化空间(创建/重命名/归档/导出/隔离) FR-2 多数据源接入(CSV/Excel/SQLite/MySQL只读) FR-3 字段画像(类型/空值/唯一/最大最小/来源变化) FR-4 只读查询(仅SELECT/拒DDL/DML/多语句/记录SQL+行数+哈希) FR-5 可视化(表格/柱/折/散点; 图表记维度指标) FR-6 数据处理(质量画像/清洗/特征工程→新产物不覆盖原始) FR-7 模型实验(分类/回归/聚类; 登记种子/划分/参数/指标/预测) FR-8 项目对话(自然语言; 先计划后执行给出证据) FR-9 报告版本(Markdown底稿/引用产物/修改恢复生成新版本) FR-10 Skills(可读说明+受控脚本, 无网络沙箱) FR-11 离线可用(无模型时确定性能力仍可用) FR-12 自然语言入口 FR-13 可复用Skills`

const COMMON_SCHEMA = {
  type:"object",
  properties:{
    area:{type:"string"},
    fr_assessment:{type:"array",items:{type:"object",properties:{fr:{type:"string"},status:{type:"string",enum:["supported","partial","missing","n/a"]},evidence:{type:"string"},note:{type:"string"}},required:["fr","status","evidence"]}},
    security_notes:{type:"array",items:{type:"string"}},
    gaps:{type:"array",items:{type:"string"}},
    summary:{type:"string"}
  },
  required:["area","fr_assessment","summary"]
}

function groupPrompt(id, title, files, focus, extra) {
  return `你是代码审计代理。在 __FDE_WORKSPACE_PATH__ 下审阅以下文件：\n${files.join("\n")}\n\n任务：评估该组代码对给定功能需求的实际支撑程度。必须真实读取文件并引用「文件路径:行号」作为 evidence。\n\n关注功能需求：${focus}\n\n公共 FR 清单：${FR_LIST}\n${extra||""}\n\n对每个相关 FR 给出 status：supported(已实现且可用)/partial(部分实现或有缺口)/missing(未实现)/n/a(该组不涉及)。同时给出 security_notes（涉及只读/敏感字段/凭证/沙箱/离线等的观察）与 gaps。务必基于真实代码，不要臆测；无法确认时标 partial 并说明。summary 用 3-5 句概括本组支撑度。`;
}

// 后端分组
const g1 = groupPrompt("g1","数据与查询","backend/northlight/data_sources.py, backend/northlight/data_assets.py, backend/northlight/connection_settings.py, backend/northlight/database.py, backend/northlight/query_service.py, backend/northlight/workspace.py, backend/northlight/domain.py, backend/northlight/models.py, backend/northlight/serialization.py","FR-2 多数据源接入 FR-3 字段画像 FR-4 只读查询 FR-1 项目空间(导出/隔离)","重点核对：是否支持 CSV/Excel/SQLite 导入与 MySQL 只读；是否有 SQL AST/只读校验/限时限行；是否记录 SQL/行数/哈希；字段画像(空值/唯一/最大最小/来源变化指纹)；原始数据不被覆盖。");
const g2 = groupPrompt("g2","分析与模型","backend/northlight/analysis_service.py, backend/northlight/ml_service.py, backend/northlight/model_jobs.py","FR-6 数据处理 FR-7 模型实验 FR-5 可视化(图表能力)","重点核对：质量画像/清洗/特征工程是否生成新产物且不覆盖原始；分类/回归/聚类；是否登记数据/特征/种子/划分/参数/指标/逐行预测；异步训练与取消。");
const g3 = groupPrompt("g3","报告与Skills与Agent","backend/northlight/report_service.py, backend/northlight/skill_service.py, backend/northlight/agent_runtime.py, backend/northlight/skills/*/SKILL.md","FR-8 项目对话 FR-9 报告版本 FR-10 Skills+沙箱 FR-11 离线可用 FR-12 自然语言入口 FR-13 可复用Skills","重点核对：自然语言是否先说明计划再执行并给证据；报告 Markdown 底稿+引用产物+版本化+HTML 导出；Skills 是否可读说明+受控脚本+无网络沙箱；无模型时确定性能力是否仍可用。");
const g4 = groupPrompt("g4","API/仓储/安全/运维","backend/northlight/api.py, backend/northlight/main.py, backend/northlight/repository.py, backend/northlight/runtime_probe.py, backend/northlight/settings.py","FR-1 项目空间 FR-4 安全查询 FR-9 报告 FR-11 离线","重点核对：API 是否覆盖 PRD 功能端点；导出是否排除 DB 密码/模型 Key/日志敏感值；凭证管理；备份/导出；只读/离线；血缘(数据/SQL/图表/模型/报告关联)。");

// 前端与测试
const g5 = groupPrompt("g5","前端","frontend/src/api.ts, frontend/src/types.ts, frontend/src/pages/*.tsx, frontend/src/components/*.tsx, frontend/src/app/App.tsx, frontend/src/features/architecture/architecture-manifest.json","FR-1 项目 FR-5 可视化 FR-8 对话 FR-9 报告 FR-10 Skills","重点核对：工作台各页面(项目/数据源/数据/探索/模型/报告/Skills/聊天/设置)是否落地；是否有图表(表格/柱/折/散点)；是否消费后端 API；报表 canvas 与 HTML 导出。");
const g6 = groupPrompt("g6","测试与脚本与技能内容","backend/tests/*.py, scripts/*.py, scripts/*.sh, sandbox/Dockerfile, fixtures/skills/**","FR-4 安全查询 FR-6 数据处理 FR-10 Skills FR-11 离线 以及性能(P95<10s@100万行)","重点核对：测试覆盖了哪些能力；sandbox 是否真实隔离；百万行性能脚本(scripts/benchmark_million.py)是否存在；skills 内容与沙箱契约；MySQL 导入脚本。");

phase("后端能力审阅");
const [r1,r2,r3,r4] = await parallel([
  ()=>agent(g1,{label:"g1-数据与查询",phase:"后端能力审阅",schema:COMMON_SCHEMA}),
  ()=>agent(g2,{label:"g2-分析与模型",phase:"后端能力审阅",schema:COMMON_SCHEMA}),
  ()=>agent(g3,{label:"g3-报告SkillsAgent",phase:"后端能力审阅",schema:COMMON_SCHEMA}),
  ()=>agent(g4,{label:"g4-API仓储安全",phase:"后端能力审阅",schema:COMMON_SCHEMA}),
]);
phase("前端与测试审阅");
const [r5,r6] = await parallel([
  ()=>agent(g5,{label:"g5-前端",phase:"前端与测试审阅",schema:COMMON_SCHEMA}),
  ()=>agent(g6,{label:"g6-测试脚本技能",phase:"前端与测试审阅",schema:COMMON_SCHEMA}),
]);
const all = [r1,r2,r3,r4,r5,r6].filter(Boolean);
return { groups: all };
"}

